/* Build 111: validated study content generated from the merged workbook. */
(() => {
  'use strict';
  const STORE='liplip-course-content-v2';
  const VERSION_KEY='liplip-bundled-study-content-version';
  const VERSION='111-36be59269c35';
  const DATA='';

  async function install(){
    if(localStorage.getItem(VERSION_KEY)===VERSION) return {version:VERSION,installed:false};
    if(typeof DecompressionStream==='undefined') throw Error('This browser cannot unpack bundled study content.');
    const compressed=Uint8Array.from(atob(DATA),char=>char.charCodeAt(0));
    const stream=new Blob([compressed]).stream().pipeThrough(new DecompressionStream('gzip'));
    const bundled=JSON.parse(await new Response(stream).text());
    let store={};
    try{store=JSON.parse(localStorage.getItem(STORE)||'{}')||{}}catch{store={}}
    const next={...store,...bundled};
    localStorage.setItem(STORE,JSON.stringify(next));
    localStorage.setItem(VERSION_KEY,VERSION);
    const result={version:VERSION,installed:true,boxes:Object.keys(bundled).length};
    window.LiplipBundledStudyContent=result;
    return result;
  }

  window.LiplipBundledStudyContentReady=install().catch(error=>{
    console.error('[liplip] bundled study content install failed',error);
    return {version:VERSION,error:String(error?.message||error)};
  });
})();
